head.script:
scwin.strNameSpace = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';    



scwin.onpageload = function () {

};



scwin.getNameSpace = function () {
    return scwin.strNameSpace;
}



/********************************************************
    Create DataList 
*******************************************************/



scwin.createCommonDatalist = function () {
    scwin.createDataListBoolean();
    scwin.createDataRefDataMap();
    scwin.createDataRefDataList();
    scwin.createDataListRef();
    scwin.createDataListOpacity();
    scwin.createDataListAutoComplete();
    scwin.createDataListCheckComboBox();
    scwin.createDataListSelectBox();
    scwin.createDataListMultiSelect();
    scwin.createDataListGridView();
    scwin.createDataListCheckBox();
    scwin.createDataListRadio();
    scwin.createDataListTreeView();
    scwin.createDataListPivot();
    scwin.createDataListFusionChart();
    scwin.createDataListFwBulletChart();
    scwin.createDataListFwFunnelChart();
    scwin.createDataListFwGanttChart();
    scwin.createDataListFwGaugeChart();
    scwin.createDataListFwPyramidChart();
}



// dataList boolean 동적 생성 (생략, true, false)
scwin.createDataListBoolean = function () {
    let strTarget = '';

    strTarget += '<w2:dataList '+ scwin.strNameSpace +' baseNode="list" repeatNode="map" id="gdl_boolean" saveRemovedData="true">';
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="label" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="value" name="name2" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<value><![CDATA[1]]></value>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[true]]></label>';
    strTarget += '<value><![CDATA[2]]></value>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<label><![CDATA[false]]></label>';
    strTarget += '<value><![CDATA[3]]></value>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';   

    $p.data.create(strTarget);
}

