*******************************************************/

scwin.getTestGroup = function (cParent='') {
    if (cParent == '')
        return document.querySelector('.tc_group_basic');

    return cParent;
}



scwin.createBasicGroup = async function (cList='', eHandler='', cID='target1', cParent='') {
    if (cID === '') 
        cID = 'target1';    

    let grp_comp = scwin.getTestGroup(cParent);

    // comp 생성
    let strTarget = '';    
    let strButton = '';
    let strInput = '';
    let strGroup = '';

    // 조건, 이벤트 설정
    strTarget += '<xf:group ' + scwin.strNameSpace + ' ' + cList + ' ' + eHandler + ' style="width:400px; height:300px; background-color:var(--ws-green-500);"></xf:group>'

    // target 생성
    scwin[cID] = await $p.dynamicCreate(
        cID,
        'group',
        strTarget,
        grp_comp
    );

    strInput += '<xf:input '+ scwin.strNameSpace +' id="" style="width:144px; height:21px; " initValue="input"></xf:input>';    

    // child 생성
    scwin.input1 = await $p.dynamicCreate(
        'input1',
        'input',
        strInput,
        scwin[cID]
    );

    strGroup += '<xf:group '+ scwin.strNameSpace +' style="width:150px; height:100px; background-color:var(--ws-orange-100);" text="group"></xf:group>'  

    scwin.group1 = await $p.dynamicCreate(
        'group1',
        'group',
        strGroup,
        scwin[cID]
    );

    strButton += '<w2:button '+ scwin.strNameSpace +' style="width:80px; height:23px;" label="button"></w2:button>'

    scwin.button1 = await $p.dynamicCreate(
        'button1',
        'button',
        strButton,
        scwin[cID]
    );
}



// gridLayout 동적 생성 (2열 x 3행 = 6 cell 그리드 배치)
//  - dynamic_error 참고 : gridLayout 은 '빈 상태'로 먼저 생성한 뒤, 각 cell(group)을 별도 dynamicCreate 로 추가한다.
scwin.createBasicGridLayout = async function (cList='', eHandler='', cID='target1', cParent='') {
    if (cID === '')
        cID = 'target1';

    let grp_comp = scwin.getTestGroup(cParent);

    // target 생성 (gridLayout : 2열 x 3행, 자식 없이 빈 상태)
    let strTarget = '';
    strTarget += '<w2:gridLayout ' + scwin.strNameSpace + ' ' + cList + ' ' + eHandler + ' style="width:400px; height:200px;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="40px 40px 40px;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;">';
    strTarget += '</w2:gridLayout>';

    scwin[cID] = await $p.dynamicCreate(
        cID,
        "gridLayout",
        strTarget,
        grp_comp
    );

    // 각 cell 을 자식 group + 내부 textbox 로 별도 생성 → 6 cell 그리드 배치
    //  - 1~2번째 group : 회색(silver) / 3~6번째 group : 흰색(white)
    //  - 1·2행 높이(gridTemplateRows 40px)로 축소되어 3행(group3/6) 및 하위가 위로 올라옴
    //  - textbox 는 setValue 로 텍스트 설정 (동적 생성 시 label 속성 미반영 대비)
    for (let i = 1; i <= 6; i++) {
        let cellBg = (i <= 2) ? 'silver' : 'white';

        // cell group 생성
        let strGroup = '<xf:group ' + scwin.strNameSpace + ' style="background-color: ' + cellBg + ';"></xf:group>';
        scwin['group' + i] = await $p.dynamicCreate(
            'group' + i,
            'group',
            strGroup,
            scwin[cID]
        );

        // group 내부 textbox 생성 후 텍스트 설정
        let strTbx = '<w2:textbox ' + scwin.strNameSpace + ' id="" style="width:150px; height:23px;"></w2:textbox>';
        scwin['tbx' + i] = await $p.dynamicCreate(
            'tbx' + i,
            'textbox',
            strTbx,
            scwin['group' + i]
        );
        scwin['tbx' + i].setValue('텍스트 ' + i);
    }
}



